def get_pipeline(settings: DocSettings, repo: ZettelRepository) -> Pipeline:
    """Wire all doc subsystem services and return a ready-to-run Pipeline."""
    from bim.commands.doc.shared.pipeline import Pipeline as _Pipeline, PipelineServices

    issuers_file = settings.paths.issuers_file
    if issuers_file is None:
        raise ValueError("DocSettings.paths.issuers_file is not set")
    services = PipelineServices(
        state_db=get_state_db(settings),
        ocr_runner=get_ocr_runner(settings),
        classifier=get_classifier(settings),
        extractor=get_extractor(settings),
        registry=_load_issuer_registry(issuers_file),
        zettel_writer=get_zettel_writer(settings, repo),
    )
    return _Pipeline(settings, services)


def get_audit_services(settings: DocSettings) -> AuditServices:
    """Bundle adapters for ``bim doc audit``.

    The audit's OCR-quality reader uses pdfminer to detect a text layer; it
    cannot compute a mean confidence (pdfminer exposes no per-page signal),
    so confidence is always ``None``. The check_ocr helper degrades to
    "missing_ocr only" when confidence is None.
    """
    from bim.commands.doc.audit.audit import AuditServices
    from bim.commands.doc.shared.hashing import sha256_file

    state_dir = settings.paths.state_dir
    issuers_file = settings.paths.issuers_file
    if state_dir is None or issuers_file is None:
        raise ValueError("DocSettings.paths.{state_dir,issuers_file} is not set")

    def _ocr_quality_reader(pdf_path: Path) -> tuple[bool, float | None]:
        from pdfminer.high_level import extract_text

        existing_text = extract_text(str(pdf_path))
        return (bool(existing_text.strip()), None)

    return AuditServices(
        state_db=get_state_db(settings),
        business_root=settings.paths.business_root,
        vault_root=settings.paths.vault_root,
        vault_documents_subdir=settings.paths.vault_documents_subdir,
        issuers_path=issuers_file,
        state_dir=state_dir,
        low_confidence_threshold=settings.ocr.low_confidence_threshold,
        ocr_quality_reader=_ocr_quality_reader,
        hash_reader=sha256_file,
    )

"""Tests for CommandResult and JSON-safe conversion."""

from __future__ import annotations

from pathlib import Path

from buvis.pybase.result import CommandResult, _json_safe


class TestCommandResult:
    def test_to_dict_produces_json_safe_dict(self) -> None:
        metadata = {
            "path": Path("notes"),
            "nested": {"items": [Path("one"), "two"]},
        }
        result = CommandResult(success=True, output="ok", metadata=metadata)

        assert result.to_dict() == {
            "success": True,
            "output": "ok",
            "error": None,
            "info": [],
            "warnings": [],
            "metadata": {"path": "notes", "nested": {"items": ["one", "two"]}},
        }

    def test_warnings_serialize_correctly(self) -> None:
        result = CommandResult(success=True, warnings=["first", "second"])

        assert result.to_dict()["warnings"] == ["first", "second"]

    def test_success_with_output(self) -> None:
        result = CommandResult(success=True, output="done")

        assert result.success is True
        assert result.output == "done"
        assert result.error is None

    def test_failure_with_error(self) -> None:
        result = CommandResult(success=False, error="failed")

        assert result.success is False
        assert result.output is None
        assert result.error == "failed"

    def test_empty_success(self) -> None:
        result = CommandResult(success=True)

        assert result.success is True
        assert result.output is None
        assert result.error is None

    def test_partial_success_with_warnings(self) -> None:
        result = CommandResult(success=True, output="ok", warnings=["warned"])

        assert result.success is True
        assert result.output == "ok"
        assert result.warnings == ["warned"]


class TestJsonSafe:
    def test_converts_nested_paths_in_dicts_and_lists(self) -> None:
        data = {
            "path": Path("root"),
            "items": [Path("a"), {"child": Path("b")}],
            "tuple": (Path("c"),),
        }

        assert _json_safe(data) == {
            "path": "root",
            "items": ["a", {"child": "b"}],
            "tuple": ["c"],
        }

@click.option("--title", default=None, help="Zettel title")
@click.option("--tags", default=None, help="Comma-separated tags")
@click.option("-a", "--answer", multiple=True, help="Template question answer as key=value")
@click.option("-l", "--list", "list_templates", is_flag=True, default=False, help="List available templates")
@click.pass_context
def create_note(
    ctx: click.Context,
    zettel_type: str | None,
    title: str | None,
    tags: str | None,
    answer: tuple[str, ...],
    *,
    list_templates: bool,
) -> None:
    if list_templates:
        from bim.dependencies import get_templates

        for name in sorted(get_templates()):
            console.print(name, mode="raw")
        return

    settings = get_settings(ctx, BimSettings)
    extra_answers: dict[str, str] = {}
    for a in answer:
        if "=" in a:
            k, v = a.split("=", 1)
            extra_answers[k] = v
    path_zettelkasten = Path(settings.path_zettelkasten).expanduser().resolve()
    if zettel_type and title:
        from bim.commands.create_note.create_note import CommandCreateNote
        from bim.dependencies import get_hook_runner, get_repo, get_templates
        from bim.params.create_note import CreateNoteParams

        try:
            params = CreateNoteParams(
                zettel_type=zettel_type,
                title=title,
                tags=tags,
                extra_answers=extra_answers,
            )
            cmd = CommandCreateNote(
                params=params,
                path_zettelkasten=path_zettelkasten,
                repo=get_repo(),
                templates=get_templates(),
                hook_runner=get_hook_runner(),
            )
        except FileNotFoundError as exc:
            console.panic(str(exc))
            return
        result = cmd.execute()
        console.report_result(
            result,
            on_success=lambda r: console.success(r.output or "Created"),
            failure_msg="Create failed",
        )
        return

    from bim.tui.create_note import CreateNoteApp

    app = CreateNoteApp(
        path_zettelkasten=path_zettelkasten,
        preselected_type=zettel_type,
        preselected_title=title,
        preselected_tags=tags,
        extra_answers=extra_answers,
    )
    app.run()


